90	        HttpResponse<String> missingFields = post("/reservations", "{\"roomNumber\": 201}");
91	        assertEquals(400, missingFields.statusCode());
92	        assertEquals("INVALID_REQUEST", json.readTree(missingFields.body()).get("error").asText());
93	
