95	        assertEquals(400, post("/reservations", RESERVATION_JSON.replace("STANDARD", "VIP")).statusCode());
96	        assertEquals(404, get("/reservations/42").statusCode());
97	        assertEquals(404, get("/reservations/abc").statusCode());
98	
